-- -----------------------------------------------------------------------------
-- 4. org_job_effect_tr - one row per applied job effect.
--    A handler inserts its effect key with ON CONFLICT DO NOTHING inside the same
--    transaction as its domain writes. Zero rows inserted = the effect already happened,
--    so the job completes without writing again. The row outlives the pg-boss job, so it
--    is also the permanent audit record of which job applied which effect.
--    Lookups always use (tenant_org_id, effect_key), served by uq_ojef_tnt_key.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.org_job_effect_tr (
  id             UUID        NOT NULL DEFAULT gen_random_uuid(),
  tenant_org_id  UUID        NOT NULL,
  effect_key     TEXT        NOT NULL,
  queue_name     TEXT        NOT NULL,
  job_id         UUID        NOT NULL,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by     TEXT        NULL,
  created_info   TEXT        NULL,
  updated_at     TIMESTAMPTZ NULL,
  updated_by     TEXT        NULL,
  updated_info   TEXT        NULL,
  updated_count  INTEGER     NOT NULL DEFAULT 0,
  deleted_at     TIMESTAMPTZ NULL,
  deleted_by     TEXT        NULL,
  deleted_info   TEXT        NULL,
  rec_status     SMALLINT    NOT NULL DEFAULT 1,
  rec_order      INTEGER     NULL,
  rec_notes      TEXT        NULL,
  is_active      BOOLEAN     NOT NULL DEFAULT true,
  CONSTRAINT pk_org_job_effect_tr PRIMARY KEY (id),
  CONSTRAINT uq_ojef_id_tenant UNIQUE (id, tenant_org_id),
  CONSTRAINT uq_ojef_tnt_key UNIQUE (tenant_org_id, effect_key),
  CONSTRAINT fk_ojef_tenant FOREIGN KEY (tenant_org_id)
    REFERENCES public.org_tenants_mst (id) ON DELETE RESTRICT,
  CONSTRAINT ck_ojef_effect_key CHECK (length(btrim(effect_key)) BETWEEN 1 AND 200),
  CONSTRAINT ck_ojef_rec_status CHECK (rec_status IN (0, 1, 2)),
  CONSTRAINT ck_ojef_deleted_inactive CHECK (rec_status = 1 OR NOT is_active)
);

COMMENT ON TABLE  public.org_job_effect_tr IS 'One row per applied background-job effect per Organization. Inserted in the same transaction as the effect, so a retried or duplicated job never applies it twice. Permanent audit of which job applied which effect.';
COMMENT ON COLUMN public.org_job_effect_tr.id IS 'Effect row UUID primary key.';
COMMENT ON COLUMN public.org_job_effect_tr.tenant_org_id IS 'Owning Organization UUID (explicit tenant filter required on every query).';
COMMENT ON COLUMN public.org_job_effect_tr.effect_key IS 'Deterministic key of one effect, for example fin.domain_event:<event_id>:loyalty-earn. Unique per Organization.';
COMMENT ON COLUMN public.org_job_effect_tr.queue_name IS 'pg-boss queue of the job that applied the effect.';
COMMENT ON COLUMN public.org_job_effect_tr.job_id IS 'pg-boss job id that applied the effect. The job row itself is deleted after its retention period; this id stays for audit.';
COMMENT ON COLUMN public.org_job_effect_tr.created_at IS 'When the effect was applied.';
COMMENT ON COLUMN public.org_job_effect_tr.created_by IS 'Actor that applied the effect, normally the consumer process.';
COMMENT ON COLUMN public.org_job_effect_tr.created_info IS 'Creation context (consumer app and version).';
COMMENT ON COLUMN public.org_job_effect_tr.updated_at IS 'When the row was last updated (set by trigger). Effects are normally never updated.';
COMMENT ON COLUMN public.org_job_effect_tr.updated_by IS 'Actor that last updated the row.';
COMMENT ON COLUMN public.org_job_effect_tr.updated_info IS 'Last update context.';
COMMENT ON COLUMN public.org_job_effect_tr.updated_count IS 'Monotonic update counter (incremented by trigger).';
COMMENT ON COLUMN public.org_job_effect_tr.deleted_at IS 'When the row was soft-deleted.';
COMMENT ON COLUMN public.org_job_effect_tr.deleted_by IS 'Actor that soft-deleted the row.';
COMMENT ON COLUMN public.org_job_effect_tr.deleted_info IS 'Soft-delete context.';
COMMENT ON COLUMN public.org_job_effect_tr.rec_status IS 'Record status: 1 active, 0 soft-deleted, 2 archived.';
COMMENT ON COLUMN public.org_job_effect_tr.rec_order IS 'Unused ordering slot, kept for the standard audit column set.';
COMMENT ON COLUMN public.org_job_effect_tr.rec_notes IS 'Optional operator notes.';
COMMENT ON COLUMN public.org_job_effect_tr.is_active IS 'True when the row is live.';
COMMENT ON CONSTRAINT pk_org_job_effect_tr ON public.org_job_effect_tr IS 'Surrogate primary key.';
COMMENT ON CONSTRAINT uq_ojef_id_tenant ON public.org_job_effect_tr IS 'Composite key for tenant-safe references.';
COMMENT ON CONSTRAINT uq_ojef_tnt_key ON public.org_job_effect_tr IS 'At most one row per Organization and effect key: the idempotency guarantee. Also the index for every lookup.';
COMMENT ON CONSTRAINT fk_ojef_tenant ON public.org_job_effect_tr IS 'Effect belongs to an existing Organization; deleting the Organization is blocked while effects exist.';
COMMENT ON CONSTRAINT ck_ojef_effect_key ON public.org_job_effect_tr IS 'Effect key is non-blank and at most 200 characters.';
COMMENT ON CONSTRAINT ck_ojef_rec_status ON public.org_job_effect_tr IS 'Standard CleanMateX rec_status values (0, 1, 2).';
COMMENT ON CONSTRAINT ck_ojef_deleted_inactive ON public.org_job_effect_tr IS 'Soft-deleted or archived rows cannot stay active.';

DROP TRIGGER IF EXISTS trg_audit_touch ON public.org_job_effect_tr;
CREATE TRIGGER trg_audit_touch BEFORE UPDATE ON public.org_job_effect_tr
  FOR EACH ROW EXECUTE FUNCTION public.fn_audit_touch_row();
COMMENT ON TRIGGER trg_audit_touch ON public.org_job_effect_tr IS 'Keeps updated_at and updated_count current.';

-- Only the consumers write or read effects, through the service connection. RLS is on
-- with no policy, so signed-in users cannot read it even if a grant were added later.
ALTER TABLE public.org_job_effect_tr ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.org_job_effect_tr FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.org_job_effect_tr TO service_role;

COMMIT;
